#!/usr/bin/env python3
"""Build the static companion from its portable evidence and chapter sources."""
from pathlib import Path
import json, html, hashlib

ROOT = Path(__file__).resolve().parents[1]
esc = html.escape
DATA = json.loads((ROOT / 'evidence/results.json').read_text())
CHAPTERS = json.loads((ROOT / 'content/deep-dive.json').read_text())['chapters']
CHAPTERS.sort(key=lambda chapter: 0 if chapter['id'] == 'execution' else 1)
SITE = json.loads((ROOT / 'content/site.json').read_text())
SCOPE = 'Mac CPU, demo-scale model, five runs per scenario'
GLOSSARY = [
 ('Temporal','Temporal stores the Event History of a Workflow Execution and schedules work for Workers.'),
 ('Durable Execution','The application can continue from recorded progress after a process fails. External computations still need their own retry and cancellation policies.'),
 ('Workflow','Workflow code decides which steps to schedule and how to respond to their outcomes. It runs in a Worker against saved Event History.'),
 ('Activity','An Activity performs external work, such as calling an inference service. An Activity may have multiple attempts.'),
 ('Worker','A Worker polls a Task Queue and runs Workflow or Activity code. The Temporal Service and the Rust inference service are separate processes.'),
 ('Task Queue','A Task Queue is a named destination for work. A Worker polls it to receive tasks it knows how to execute.'),
 ('Event History','An Event History records the events needed to reconstruct a Workflow Execution, including Activity results and scheduling decisions.'),
 ('Retry Policy','A Retry Policy controls repeated attempts after a retryable failure. Its attempt limit and waiting intervals have different roles.'),
 ('Non-Retryable Error','An application can mark a failure as non-retryable when repeating the same Activity request is not the chosen response.'),
 ('Heartbeat','An Activity records a Heartbeat to report liveness and optionally progress details. This build records a seed, not a sampler checkpoint.'),
 ('Heartbeat Timeout','This timeout limits silence since the last Heartbeat received by the Temporal Service. It is not a clock that starts at the kill command.'),
 ('Start-To-Close Timeout','This timeout limits an Activity attempt after it starts. It does not by itself bound the entire Workflow duration.'),
 ('Replay','Replay runs Workflow code against saved Event History. Completed Activity results can come from that record without executing the Activity again.'),
 ('Replayer','A Replayer checks whether Workflow code is compatible with a saved history. The research check covers one code transition and one saved history.'),
 ('Sampler','A sampler repeatedly calls a learned velocity network and updates a noisy state. The Rust service owns this loop in the measured build.'),
 ('Ensemble','An ensemble contains several generated fields. The reported physics metrics in this build describe their mean.'),
 ('NVR','The negative-value rate measures the share of precipitation cells below zero. The Activity gate requires NVR equal to 0 by default.'),
 ('MCE','The mass conservation error measures relative disagreement between the generated precipitation mean and the requested coarse mean. The default limit is 1e-3.'),
 ('DE','Divergence error is a reported diagnostic. It does not control acceptance in the Activity physics gate.'),
 ('Idempotency','An idempotency policy defines how repeated requests affect an external service. This build has no Activity idempotency key, and a seed does not prevent repeated work.'),
 ('ONNX Runtime','ONNX Runtime evaluates the exported neural network graph. It does not own the Temporal Workflow.'),
 ('gRPC','gRPC is the remote-call protocol used between the Go Infer Activity and the Rust inference service.')
]

def source_link(label, href):
 return f'<a href="{esc(href)}">{esc(label)}</a>'

CODE = {
 'execution': ('workflow-options','The Workflow chooses separate Activity options.'),
 'retries': ('physics-check','Infer turns an unacceptable result into a Non-Retryable Error.'),
 'heartbeats': ('heartbeat-loop','The Activity records the seed while it waits for the RPC.'),
 'replay': ('replay-test','The Replayer checks a saved history without rerunning inference.'),
 'reports': ('report-fallback','Report returns a template when the agent call fails.')
}

def code_panel(key, label):
 text=(ROOT / 'code' / f'{key}.go.txt').read_text()
 return f'''<details class="code-details"><summary>{esc(label)}</summary><p class="code-caption">This excerpt comes verbatim from research commit <code>9aa337d</code>. It is a source excerpt, not a standalone Go program.</p><div class="code-toolbar"><a href="code/{key}.go.txt">Open the source excerpt</a><button class="copy-button" data-copy="code-{key}" type="button">Copy code</button></div><pre><code id="code-{key}">{esc(text)}</code></pre></details>'''

chapter_html=[]
for c in CHAPTERS:
 parts=[f'<article class="chapter" id="{c["id"]}"><p class="eyebrow">The technical guide</p><h2>{esc(c["title"])}</h2><p class="chapter-intro">{esc(c["intro"])}</p>']
 for sec in c['sections']:
  parts.append(f'<h3>{esc(sec["heading"])}</h3>')
  parts.extend(f'<p>{esc(p)}</p>' for p in sec['paragraphs'])
 if c['id'] in CODE:parts.append(code_panel(*CODE[c['id']]))
 parts.append('<p class="source">The chapter follows the <a href="evidence/results.json">frozen run data</a>, <a href="evidence/history-excerpts.json">sanitized history excerpts</a> and <a href="code/source-manifest.json">pinned code manifest</a>. The <a href="#references">primary-source reading list</a> explains the general Temporal mechanisms.</p></article>')
 chapter_html.append(''.join(parts))
rows=[]
for g in DATA['groups']:
 rows.append(f'<tr><td>{esc(g["label"])}</td><td>{g["total"]}</td><td>{g["range"]}</td><td>{g["attempts"]}</td><td>{g["samples"]}</td></tr>')
options=''.join(f'<option value="{g["key"]}"'+(' selected' if g['key']=='f1-hb' else '')+f'>{esc(g["label"])}</option>' for g in DATA['groups'])
toc=''.join(f'<a href="#{c["id"]}">{esc(c["title"])}</a>' for c in CHAPTERS)
glossary=''.join(f'<article class="glossary-entry"><h3>{esc(term)}</h3><p>{esc(definition)}</p></article>' for term,definition in GLOSSARY)
repo=SITE['repo_url']; canonical=SITE['site_url']
embedded_data = json.dumps(DATA).replace('<', '\\u003c')
page=f'''<!doctype html>
<html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"><title>Temporal around a sampler | Arun Sharma</title><meta name="description" content="An illustrated guide to Temporal Workflows, retries, physics checks, Heartbeats and replay, grounded in a measured laptop CPU research build."><link rel="canonical" href="{canonical}"><meta property="og:title" content="Durable execution around a sampler"><meta property="og:description" content="Explore the request path, failure experiments, replay mechanics and evidence behind a research build."><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#141414"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head>
<body><a class="skip" href="#start">Skip to the explanation</a><header class="site-header"><div class="header-inner"><a class="brand" href="#top"><span class="brand-mark" aria-hidden="true">↻</span>Temporal / Sampler</a><nav id="site-nav" aria-label="Main navigation"><a href="#start">Start here</a><a href="#experiments">Experiments</a><a href="#guide">Deep dive</a><a href="#evidence">Evidence</a><a href="{repo}">Repository ↗</a></nav><button class="icon-button" id="theme-toggle" type="button" aria-label="Switch to light theme">Light</button><button class="icon-button" id="menu-toggle" type="button" aria-controls="site-nav" aria-expanded="false">Menu</button></div><div class="progress" id="reading-progress" aria-hidden="true"></div></header>
<main id="top"><section class="hero wrap"><p class="eyebrow">An illustrated research companion</p><h1>Durable execution<br>around a sampler.</h1><div class="hero-rule"></div><p class="lede">Temporal helps a long-running job continue after a failure. This guide follows a climate model request and shows what happens when the program managing it stops.</p><p class="byline">Arun Sharma, University of Minnesota, Twin Cities</p><div class="resources"><a class="pill primary" href="#start">Start with the idea <span aria-hidden="true">↓</span></a><a class="pill" href="#worked-example">Follow an example</a><a class="pill" href="#experiments">Explore the experiments</a><a class="pill" href="downloads/replay-deck.pdf">Read the slide deck ↗</a><a class="pill" href="{repo}">Browse the source ↗</a></div><p class="hero-note">This companion supports a proposed Replay 2027 talk. The experiments use a research system. The measurements come from one Mac CPU and a demo-scale model.</p></section>
<section class="section beginner" id="start"><div class="wrap reading"><p class="eyebrow">New to Temporal?</p><h2>Start with a job that can survive a restart.</h2><p>Imagine an application that asks a model to generate a detailed climate map, checks the result and writes a report. The model call can take time. If the program managing the job stops, the application still needs to know which steps finished and what to do next.</p><p>Temporal is a platform for coordinating that kind of job. Its service records a job's progress and makes tasks available to application programs called Workers. A Worker runs the application code. If a Worker disappears, another available Worker can use the recorded history to continue the job.</p><div class="primer-terms"><article><h3>A Workflow is the plan.</h3><p>Workflow code decides the order of steps and how to respond to their results. In this guide, it schedules inference and then reporting.</p></article><article><h3>An Activity does the work.</h3><p>An Activity performs work outside the Workflow's decisions. Here, Infer calls the model service, and Report prepares the explanation.</p></article><article><h3>Event History is the record.</h3><p>The Temporal Service records events, including completed Activity results. Workflow code can use that history to reconstruct its progress.</p></article></div><p>For example, Infer can finish and Temporal can record its result. If the Worker then stops, another Worker can reconstruct the Workflow and continue toward Report. The recorded result supplies the completed inference step.</p><div class="callout"><p><strong>Retry and replay answer different questions.</strong> A retry starts another Activity attempt after a failure. Replay runs Workflow code against saved history to reconstruct its decisions or check compatibility. Replay can use a recorded Activity result without calling that Activity again.</p><p>A retry may repeat external work. Temporal does not automatically stop a separate model service or save the model's partial computation.</p></div><p class="source">This introduction is a conceptual example. The <a href="#experiments">failure explorer</a> shows the recorded research results. The <a href="#execution">execution chapter</a> explains the mechanisms in more detail. The <a href="#glossary">glossary</a> defines the terms used throughout the guide.</p></div></section>
<section class="section" id="worked-example"><div class="wrap reading worked-example"><p class="eyebrow">A step-by-step example</p><h2>Follow a request through failure and replay.</h2><p>Imagine that a climate-map request reaches the Workflow. This example is conceptual. It illustrates the mechanics and does not report a measured run.</p><p class="source">Follow the stages to see the work and the record change. The record is a simplified illustration of Event History, not a live Temporal execution or a complete event log.</p><div class="example-controls" id="example-controls" hidden><button type="button" id="example-previous" aria-controls="example-steps">← Previous</button><span id="example-progress" role="status" aria-live="polite" aria-atomic="true"></span><button type="button" id="example-next" aria-controls="example-steps">Next →</button></div><ol class="example-steps" id="example-steps"><li data-stage="1"><h3>The Workflow asks for inference.</h3><p>A Worker runs the Workflow code. The Workflow asks Temporal to schedule the Infer Activity, which calls the model service. The Workflow waits for the Activity's result.</p><p class="example-status"><strong>The job is waiting for:</strong> A result from Infer.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>The Workflow has started, and Infer has been scheduled.</p></div></li><li data-stage="2"><h3>The first Activity attempt fails.</h3><p>Imagine that the model service is temporarily unavailable, so Infer returns a retryable connection error before the sampler starts. The Workflow is still waiting for the Activity's final outcome.</p><p class="example-status"><strong>What failed:</strong> An Activity attempt. The Workflow has not necessarily failed.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>Infer remains scheduled. A retryable attempt failure may be managed as retry state and need not appear as a separate failure event in Event History.</p></div></li><li data-stage="3"><h3>Temporal arranges another attempt.</h3><p>The Retry Policy allows another try. After the policy's waiting period, an available Worker runs Infer again. The service has returned, so this attempt runs the sampler, passes the physics gate and prepares a result for Temporal. The gate checks measurements on the average of the generated fields.</p><p class="example-status"><strong>What ran again:</strong> The Infer Activity and its model call. Retry depends on the error and the configured policy.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>Infer remains scheduled while the new attempt works. The successful result is not recorded until Temporal receives the completion.</p></div></li><li data-stage="4"><h3>Temporal records the result.</h3><p>The Temporal Service records the successful Activity outcome in the Workflow's Event History. The Workflow can use that result to decide what comes next.</p><p class="example-status"><strong>What is saved:</strong> The Activity outcome in Event History.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>Infer is scheduled, and its successful outcome is recorded.</p></div></li><li data-stage="5"><h3>The Worker stops before Report is scheduled.</h3><p>Imagine that the Worker disappears after the result is recorded and before the Workflow processes that result and schedules Report. Temporal retains the Event History. Another available Worker can pick up a Workflow Task, which tells it to run the Workflow code.</p><p class="example-status"><strong>What remains:</strong> The recorded Workflow history.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>The successful Infer outcome remains in Event History. The Worker disappearing does not itself add a Worker-killed event to this history.</p></div></li><li data-stage="6"><h3>Replay restores the decision path.</h3><p>The replacement Worker runs the Workflow code against the saved history. During replay, Temporal supplies the recorded Infer result. The completed Infer Activity is not called again to reconstruct that progress. The Workflow then schedules Report and can finish when Report succeeds.</p><p class="example-status"><strong>What replay uses:</strong> The saved result. Replay is distinct from the earlier Activity retry.</p><div class="example-record"><strong>The illustrated record at this stage</strong><p>Replay reads the existing history. When the Workflow continues and schedules Report, Temporal records that decision after the Workflow Task completes.</p></div></li></ol><div class="callout"><p><strong>The boundary matters.</strong> A retry can repeat an external model call. A different failure may leave a sampler running after its caller disconnects. Replay of a recorded completed Activity result does not repeat that call merely to rebuild Workflow state. Temporal does not automatically cancel or checkpoint a separate sampler. In this build, a failed physics check produces a Non-Retryable Error and stops Infer retries.</p></div><p class="source">The <a href="#experiments">failure explorer</a> contains measured scenarios. Select “Service down briefly” to see a related outage experiment. Its first retry start remains UNVERIFIED. The <a href="#replay-lab">replay illustration</a> explains a separate compatibility check.</p></div></section>
<section class="wrap" aria-labelledby="request-heading"><div class="teaser"><div class="teaser-head"><div><p class="eyebrow">Follow the request</p><h2 id="request-heading">Each component owns a different job.</h2></div><span class="scope">Select a component to see what it does.</span></div><div class="diagram-grid" id="architecture"><button class="node" data-node="gateway" aria-pressed="false">Go gateway<span>Starts a Workflow</span></button><span class="arrow" aria-hidden="true">→</span><button class="node" data-node="service" aria-pressed="false">Temporal Service<span>Saves events and schedules tasks</span></button><span class="arrow arrow-down" aria-hidden="true">→</span><div class="worker-group"><span class="group-label">The Worker runs this code.</span><button class="node" data-node="workflow" aria-pressed="true">Workflow<span>Chooses the next step</span></button><button class="node" data-node="activities" aria-pressed="false">Infer + Report<span>Make external calls</span></button></div><span class="arrow arrow-down" aria-hidden="true">→</span><div class="remote-group"><button class="node" data-node="rust" aria-pressed="false">Rust + ONNX Runtime<span>Runs the sampler</span></button><button class="node" data-node="report" aria-pressed="false">Optional LLM agent<span>Returns explanatory text</span></button></div></div><div class="detail-panel" id="node-detail" aria-live="polite"><strong>The Workflow chooses the order.</strong> It schedules Infer, waits for its result, then schedules Report. The Worker executes this code. The Temporal Service records the decisions and outcomes.</div><p class="source">The diagram summarizes component ownership. Infer calls Rust through gRPC, and Report can call the agent through HTTP. One request went through the gateway, while the experiment campaign started Workflows through the Temporal CLI.</p></div></section>
<section class="section" id="overview"><div class="wrap"><div class="two-column"><div><p class="eyebrow">Start with the idea</p><h2>The saved decision and the running computation are different things.</h2></div><div><p>A sampler turns noise into a generated field through repeated model calls. PC-RF uses this idea for climate downscaling. A single request can perform enough work that restarting it matters.</p><p>Temporal saves a job's decisions and results so its orchestration can continue after a Worker fails. The model computation runs in a separate Rust service. Saving the job's progress does not automatically cancel that service or checkpoint its sampler.</p><p>The key question is what happens when the caller disappears while the computation is still running. This research build makes that failure visible and measures the next attempt.</p></div></div><div class="paths"><article class="path"><span class="number" aria-hidden="true">01</span><h3>You can learn the path.</h3><p>Start with the component diagram and the glossary. Then follow a request from input through inference, acceptance and reporting.</p><a href="#execution">Understand the components →</a></article><article class="path"><span class="number" aria-hidden="true">02</span><h3>You can inspect a failure.</h3><p>Choose an observed scenario. Compare Activity attempts with actual sampler runs, then inspect the saved run intervals.</p><a href="#experiments">Open the failure explorer →</a></article><article class="path"><span class="number" aria-hidden="true">03</span><h3>You can inspect the evidence.</h3><p>Read the pinned code excerpts, timing definitions and limits. Download the numeric records behind the figures.</p><a href="#evidence">Follow the evidence →</a></article></div><div class="callout"><p><strong>The scope is part of the result.</strong> This is a research system, not a commercial production deployment. The model uses a 64 by 64 tile, base width 32, no attention and brief synthetic training. The Temporal dev server uses a local database file.</p></div></div></section>
<section class="section" id="experiments"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">The failure explorer</p><h2>Choose what went wrong.</h2></div><p class="intro">Choose a failure, then choose an individual saved run. The summary shows the group median, and the timeline shows that run. The controls do not run Temporal or simulate a new measurement.</p></div><div class="lab"><div class="lab-controls"><div class="control"><label for="scenario-select">Observed scenario</label><select id="scenario-select">{options}</select></div><span class="scope">{SCOPE}</span></div><p class="source">An Activity attempt is one try at Infer. A sampler run is actual model computation. A median is the middle value after the five measurements of the same quantity are ordered from smallest to largest. The selected timeline starts with the run whose Workflow duration is the middle value. That run need not have the middle failure-to-next-attempt interval. When recorded, the failure-to-next-attempt interval runs from the kill or stop command to the next observed Activity start.</p><div class="callout small-callout"><p><strong>How does Temporal wait for a retry?</strong> A Heartbeat is a signal from an Activity that its Worker is alive. A Heartbeat Timeout limits the silence since the last signal received by the Temporal Service. Start-To-Close Timeout limits how long one started Activity attempt may run.</p><p>After a failure, backoff is a planned wait before retrying. A retry also needs an available Worker and time for the task to reach it. See the <a href="#heartbeats">Heartbeat chapter</a> and <a href="#glossary">glossary</a> for more detail.</p></div><div id="scenario-summary" aria-live="polite"><p>The Worker-killed scenario uses a 10 s Heartbeat Timeout. Its median Workflow time was 32.320 seconds.</p></div><div class="timeline-wrap"><div class="timeline-title"><h3>The selected run shows when the sampler worked.</h3><label for="run-select">Saved run<select id="run-select" aria-label="Saved run"></select></label></div><div id="timeline" role="img" aria-label="Sampler timing for a recorded run"></div><div class="timeline-legend"><span><i class="dot"></i>The first sampler run</span><span><i class="dot green"></i>The second sampler run</span><span id="kill-legend"><i class="dot amber"></i>The Worker kill command</span></div><p class="source">Each bar shows when the model service ran the sampler. The horizontal position shows time since the experiment runner began the request. The Workflow duration starts later, at the Workflow-start event in Event History. These are different starting points. A sampler end offset can exceed the Workflow duration without proving that the sampler ended after the Workflow. The original saved timestamps place the default run's sampler end before its final Workflow event. The experiment did not independently verify clock synchronization or timestamp precision. The published data keeps offsets and durations but omits the original absolute timestamps.</p><p class="source">An Activity attempt can fail before the sampler starts, so attempts and sampler runs can differ. A selected run is an individual observation, not a group median. Bars can overlap when the original Rust task continues after the Worker disconnects and another attempt starts. The plot does not mark an unrecorded retry start.</p></div><details><summary>You can inspect every run in this scenario.</summary><div class="table-wrap" tabindex="0"><table><thead><tr><th>Run</th><th>Workflow seconds</th><th>Infer attempts</th><th>Sampler runs</th><th>Failure to next attempt</th></tr></thead><tbody id="run-table"></tbody></table></div></details><p class="source">The source is <a href="evidence/results.json">the curated run record</a>. You can also download <a href="evidence/runs.csv">the CSV table</a>. All timings describe one Apple M4 Pro laptop CPU with the demo-scale model.</p></div></div></section>
<section class="section" id="finding"><div class="wrap two-column"><div><p class="eyebrow">The central finding</p><h2>A shorter wait still repeated the sampler.</h2><p>Both groups recorded Heartbeats. The comparison changed whether Infer had a 10 s Heartbeat Timeout. Both groups kept the 2-minute Start-To-Close Timeout.</p><p>The failure-to-next-attempt medians are consistent with those chosen settings. The interval includes retry backoff, Worker availability and dispatch delay. It does not isolate the server's internal timeout detector.</p></div><div><span class="scope">{SCOPE}</span><div class="bar-compare"><div class="bar-row"><span>The Heartbeat Timeout was 10 s.</span><div class="bar-track"><div class="bar-fill" style="width:8.29417%"></div></div><span class="bar-value">9.953 s</span></div><div class="bar-row"><span>No Heartbeat Timeout was set.</span><div class="bar-track"><div class="bar-fill purple" style="width:98.2275%"></div></div><span class="bar-value">117.873 s</span></div></div><p class="source">Both bars use an elapsed-time axis ending at the chosen 120 s Start-To-Close setting. These are failure-to-next-attempt medians, not measured timeout-fire instants.</p><div class="callout small-callout"><p>Recovery ran the sampler twice in all 15 Worker-kill runs. A Heartbeat Timeout saved waiting time in this build and did not save compute.</p></div><a href="assets/figures/c1_detection_strip.png">Open the original run-level figure →</a></div></div></section>
<section class="section" id="guide"><div class="wrap"><p class="eyebrow">The technical guide</p><div class="reading"><h2>The mechanics explain the outcome.</h2><p class="muted">These chapters separate the model, the orchestration and the evidence. You can read them in order or jump to the mechanism you need.</p></div><div class="chapters-layout"><aside class="chapter-toc" aria-label="Technical chapters">{toc}<a href="#replay-lab">Explore a replay mismatch</a><a href="#glossary">Look up a term</a></aside><div>{''.join(chapter_html)}</div></div></div></section>
<section class="section" id="replay-lab"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">A replay illustration</p><h2>The next command must fit the history.</h2></div><p class="intro">Scheduling asks Temporal to arrange work. A timer asks Temporal to wait. This conceptual illustration compares the order of Workflow decisions with saved history. The recorded research test and its exact error appear below.</p></div><div class="lab"><label for="replay-variant">Workflow code to compare</label><select id="replay-variant"><option value="same">The code schedules Infer before Report.</option><option value="timer">The code inserts a timer before Infer.</option></select><div id="replay-output" aria-live="polite"></div><details><summary>You can read the recorded mismatch.</summary><p>The scratch edit inserted <code>workflow.Sleep</code> before Infer. The saved history expected Infer at that point, and the Replayer returned this error.</p><pre><code>[TMPRL1100] lookup failed for scheduledEventID to activityID: scheduleEventID: 5, activityID: 5</code></pre><p>The edit was removed and the test passed again. The replay test covers one code transition and one saved history. It does not establish compatibility for arbitrary changes.</p></details></div></div></section>
<section class="section" id="glossary"><div class="wrap"><p class="eyebrow">The terms, in plain language</p><h2>You can look up the moving parts.</h2><div class="reading"><label for="glossary-search">Search the glossary</label><input type="search" id="glossary-search" placeholder="Try Worker, replay or sampler" autocomplete="off"><p id="glossary-count" aria-live="polite">The glossary explains the terms used in this guide.</p></div><div class="glossary-grid">{glossary}</div></div></section>
<section class="section" id="evidence"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">The evidence trail</p><h2>Every result has a bounded meaning.</h2></div><p class="intro">The campaign has eight scenario groups with five runs each. The table shows Workflow duration, which includes more than the inference call.</p></div><span class="scope">{SCOPE}</span><div class="table-wrap" tabindex="0"><table class="evidence-table"><thead><tr><th>Scenario</th><th>Median seconds</th><th>Observed range</th><th>Infer attempts</th><th>Sampler runs</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="source">The invalid-output request uses 20 steps with projection disabled. The standard request uses 1500 steps and 4 ensemble members. Their durations answer different questions. The other settings are recorded in <a href="evidence/results.json">the evidence JSON</a>.</p><div class="two-column"><div><h3>The timing definitions matter.</h3><p>Workflow time runs from the Workflow-start event to its last history event. Infer attempts come from the attempt field on the last Infer start event. The parser does not count start events as attempts.</p><p>Sampler counts come from completion records inside the Rust sampling task. Failure-to-next-attempt time runs from the recorded kill or stop command to the next distinct observed Activity start.</p></div><div><h3>Some claims remain UNVERIFIED.</h3><ul><li>The first retry start in the brief outage remains UNVERIFIED.</li><li>Full field identity and reproducibility on other hardware remain UNVERIFIED.</li><li>Remote CI and container builds of the research runtime remain UNVERIFIED.</li><li>Real sampler cancellation, graceful shutdown and real-traffic load need further experiments.</li></ul></div></div><div class="callout"><p>The physics gate checks the ensemble mean only. The live unavailable-agent case returned the template. Only a mocked test reached the separate report-unavailable Workflow branch. The replacement experiment covers one code transition, and the separate replay test uses one saved history.</p></div><div class="downloads"><a class="download" href="evidence/results.json">The experiment record contains the data.<span>The JSON includes all 40 scenario runs and their summaries.</span></a><a class="download" href="evidence/runs.csv">The CSV supports independent inspection.<span>The table keeps run times, attempts and sampler counts separate.</span></a><a class="download" href="evidence/history-excerpts.json">The history excerpts show the decisions.<span>The sanitized fields preserve scheduled options and timeout types.</span></a></div><p class="source">The <a href="evidence/provenance.json">provenance record</a> pins the frozen inputs to research commit <code>9aa337d</code>. This companion publishes curated evidence and source excerpts. It excludes raw histories, runtime logs and model artifacts. The full Temporal branch is not included.</p></div></section>
<section class="section" id="materials"><div class="wrap"><p class="eyebrow">Keep exploring</p><h2>You can take the material with you.</h2><div class="downloads"><a class="download" href="downloads/replay-deck.pdf">The PDF carries the proposed talk.<span>The visually reviewed deck includes the main slides and appendix.</span></a><a class="download" href="downloads/replay-deck.pptx">The PowerPoint includes speaker notes.<span>The deck remains a draft, and its live pace is UNVERIFIED.</span></a><a class="download" href="{repo}">The repository contains this website.<span>The source includes chapters, evidence, excerpts and site checks.</span></a></div><p>The companion builds on the explanation style of the <a href="https://arunshar.com/projects/pcrf/">PC-RF project page</a>. That page discusses the model and its wider research history. Its other benchmarks use different configurations and must not be substituted for this Temporal experiment.</p><p>The <a href="https://github.com/arunshar/pc-rf">PC-RF repository</a> contains the wider modeling project. This companion's <a href="code/source-manifest.json">source manifest</a> identifies the exact excerpts used here. Those excerpts are educational references, not a complete runtime distribution.</p></div></section>
<section class="section" id="references"><div class="wrap reading"><p class="eyebrow">Primary-source reading</p><h2>The documentation explains the general mechanisms.</h2><ul><li><a href="https://docs.temporal.io/workflow-execution">Temporal's Workflow Execution documentation</a> explains the saved execution and its lifecycle.</li><li><a href="https://docs.temporal.io/encyclopedia/detecting-activity-failures">Temporal's Activity failure documentation</a> explains timeout clocks and Heartbeats.</li><li><a href="https://docs.temporal.io/develop/go/testing-suite">Temporal's Go testing documentation</a> explains test environments and replay checks.</li><li><a href="https://arunshar.com/projects/pcrf/">The PC-RF project page</a> explains the generator and distinguishes physical constraints from predictive usefulness.</li></ul><p class="source">The documentation explains mechanisms. The downloadable records support this guide's measured claims. The model, code and environment are pinned to the research snapshot, so a newer SDK may require different implementation details.</p></div></section></main><footer class="site-footer"><div class="wrap footer-row"><div><p>Arun Sharma, University of Minnesota, Twin Cities</p><p>This is an independent research companion for a proposed Replay 2027 talk.</p><p><a href="{repo}">Website source</a> · <a href="LICENSE">MIT license</a> · <a href="assets/fonts/OFL-Inter.txt">Font license</a></p></div><a href="#top" class="back-top">Return to the beginning ↑</a></div></footer><noscript><p class="no-js">JavaScript is disabled. The full guide, evidence table, code excerpts and downloads remain readable. The interactive controls require JavaScript.</p></noscript><script id="experiment-data" type="application/json">{embedded_data}</script></body></html>'''
